SELECT a COLLATE NOCASE FROM t;
SELECT a FROM t WHERE a = 'x' COLLATE NOCASE;
SELECT a FROM t ORDER BY a COLLATE NOCASE DESC, b COLLATE BINARY;
SELECT a FROM t GROUP BY a COLLATE RTRIM;
SELECT DISTINCT lower(a) COLLATE NOCASE AS a FROM t;
CREATE INDEX idx ON t (a COLLATE NOCASE);
CREATE UNIQUE INDEX idx ON t (a COLLATE NOCASE DESC, b);
